import{_ as o,c as s,o as r,ag as a}from"./chunks/framework.C8hRoDJf.js";const e="/docs/assets/6.4Lq6805K.png",l="/docs/assets/7.Ch-jRv0K.png",i="/docs/assets/8.DyRMGjU2.png",n="/docs/assets/9.DZdi9Uk8.png",p="/docs/assets/1.B2IEpuyJ.png",g="/docs/assets/2.SL4CEvpx.png",c="/docs/assets/3.GQp9pugb.jpg",h="/docs/assets/4.CgjEQEcx.jpg",m="/docs/assets/5.BTsU-TvM.jpg",P=JSON.parse('{"title":"常见问题及其解决方式","description":"","frontmatter":{},"headers":[],"relativePath":"player/solutions.md","filePath":"player/solutions.md"}'),d={name:"player/solutions.md"};function _(f,t,u,b,x,q){return r(),s("div",null,t[0]||(t[0]=[a('<h1 id="常见问题及其解决方式" tabindex="-1">常见问题及其解决方式 <a class="header-anchor" href="#常见问题及其解决方式" aria-label="Permalink to &quot;常见问题及其解决方式&quot;">​</a></h1><h2 id="游戏登录不上-加载黑屏" tabindex="-1">游戏登录不上/加载黑屏 <a class="header-anchor" href="#游戏登录不上-加载黑屏" aria-label="Permalink to &quot;游戏登录不上/加载黑屏&quot;">​</a></h2><ol><li>尽量在良好的网络环境下进行游戏，比如高速 wifi 或者 5G 网络。</li><li>登录时保持耐心，<strong>因为首次登陆或者游戏内容更新时，玩家端需要从服务器下载大量更新资源（大约 10MB），这个过程可能需要一些时间。</strong>（比如在玩手游的时候，会有一个进度条 xxx/xxx），而这个版本会是黑屏+进度旋转动画。在游戏资源下载完毕就能显示内容了。</li><li>在看到群消息说要进行游戏内容更新时，可以在玩完后选择退出游戏，这样的话，下次内容更新完后，再登录就会到登录页面而非直接的游戏页面。资源会进行分批下载。更快看到实际内容。</li><li>如果上述方式无效，可以在群里喊一下或者直接私聊管理员寻求其他解决方案。</li></ol><h2 id="多设备怎么实现数据共享" tabindex="-1">多设备怎么实现数据共享 <a class="header-anchor" href="#多设备怎么实现数据共享" aria-label="Permalink to &quot;多设备怎么实现数据共享&quot;">​</a></h2><ol><li><p>该游戏为单机游戏， <strong>此处的单机指的是玩家数据存储在玩家本地，服务器不存储任何玩家数据。</strong> 账号登录、宠物图片、字体等资源加载还是依赖网络连接的。</p></li><li><p><strong>由于上述原因，玩家从一个浏览器切换到另外一个浏览器，或是从 PC 端切换到移动端。若要实现账号数据同步。则需要执行以下操作</strong>：</p><ol><li><p>旧设备登录账号，打开个人信息，点击上传数据。</p><p><img src="'+e+'" alt="image-20240629104136286"></p><p><img src="'+l+'" alt="image-20240629104136286"></p></li><li><p>新设备登录 <strong>同一账号</strong>，打开个人信息，读取数据，等待页面刷新。</p><p><img src="'+i+'" alt="image-20240629104136286"></p><p><img src="'+n+'" alt="image-20240629104136286"></p></li></ol></li></ol><h2 id="pc-端挂机无效或挂机卡顿" tabindex="-1">PC 端挂机无效或挂机卡顿 <a class="header-anchor" href="#pc-端挂机无效或挂机卡顿" aria-label="Permalink to &quot;PC 端挂机无效或挂机卡顿&quot;">​</a></h2><ol><li><p>建议使用 <a href="https://www.microsoft.com/zh-cn/edge/download?form=MA13FJ" target="_blank" rel="noreferrer">微软 Edge 浏览器</a> 或者 <a href="https://www.google.cn/chrome/" target="_blank" rel="noreferrer">谷歌 Chrome 浏览器</a>。</p></li><li><p>按下述步骤更改浏览器配置：</p><p><strong>Edge 浏览器</strong></p><ol><li>在地址栏输入 <strong>edge://settings/system</strong> 跳转到浏览器设置界面</li></ol><p><img src="'+p+'" alt="image-20240629103957477"> 2. 选中左侧列表中的 <strong>系统与性能</strong>, 再找到右侧的 <strong>从不让这些站点进入睡眠模式</strong>，<strong>添加游戏网址：<a href="http://127.0.0.1:12000" target="_blank" rel="noreferrer">http://127.0.0.1:12000</a></strong></p><p><strong>谷歌 Chrome 浏览器</strong></p><ol><li>在地址栏输入 <strong>chrome://settings/performance</strong> 跳转到浏览器设置界面</li></ol><p><img src="'+g+'" alt="image-20240629104136286"> 2. 选中左侧列表中的<strong>性能</strong>, 再找到右侧的 <strong>始终让这些网站保持活动状态</strong>，<strong>添加游戏网址：<a href="http://127.0.0.1:12000" target="_blank" rel="noreferrer">http://127.0.0.1:12000</a></strong></p></li></ol><h2 id="移动端怎么实现后台挂机" tabindex="-1">移动端怎么实现后台挂机 <a class="header-anchor" href="#移动端怎么实现后台挂机" aria-label="Permalink to &quot;移动端怎么实现后台挂机&quot;">​</a></h2><ol><li><p>建议在 <strong>微信</strong> 中打开游戏网址，开启你的游戏， 非微信浏览器可以仿照以下方式进行对应设置。</p><p><img src="'+c+'" alt="image-20240629104136286"></p><p><img src="'+h+'" alt="image-20240629104136286"></p><p><img src="'+m+'" alt="image-20240629104136286"></p></li></ol><h2 id="移动端账号数据丢失异常原因判断及解决方式" tabindex="-1">移动端账号数据丢失异常原因判断及解决方式 <a class="header-anchor" href="#移动端账号数据丢失异常原因判断及解决方式" aria-label="Permalink to &quot;移动端账号数据丢失异常原因判断及解决方式&quot;">​</a></h2><ol><li>游戏并没有根据市面上的机型去做适配。但玩家可在游戏前参考以下的预防措施。 <ol><li>QQ 浏览器：推荐使用。</li><li>微信浏览器：如果个人因工作或其他原因需要在当前手机上切换微信登录账号的，请不要使用微信进行游戏。</li><li>其他浏览器：如果浏览器是需要登录相关账号的，建议不要使用，这部分的浏览器中，也存在由于浏览器账号切换导致游戏数据丢失的风险。（玩家可根据自己的手机机型进行测试）。</li><li>养成每天上传一次数据的习惯，这样即使数据丢失了，也存在通过云端找回数据存储的可能性（机会渺茫）。</li></ol></li></ol><h2 id="副本图纸掉落-礼包开启道具概率设定" tabindex="-1">副本图纸掉落/礼包开启道具概率设定 <a class="header-anchor" href="#副本图纸掉落-礼包开启道具概率设定" aria-label="Permalink to &quot;副本图纸掉落/礼包开启道具概率设定&quot;">​</a></h2><ol><li>目前设定就是随机概率掉落。玩家获得 A 道具很多， B 道具没有的现象是正常的。</li><li>玩家可以通过多次消耗货币来换取更多开启次数。</li></ol>',13)]))}const C=o(d,[["render",_]]);export{P as __pageData,C as default};
